head.script:
scwin.getType1 = function(info) {
    debugger;
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    var inputType = dataList1.getCellData(rowIndex, colIndex);
    switch (inputType) {
        case "0":
            returnInfo = {
                id: "dynamic_select_" + rowIndex + "_" + colIndex,
                inputType: "select",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList4",
                    label: "col1",
                    value: "col2"
                }
            }
            break;
        case "autoComplete":
            returnInfo = {
                id: "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
                inputType: "autoComplete",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList4",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "textImage":
            if (globalViewType) {
                returnInfo = {
                    id: "dynamic_textImage_" + rowIndex + "_" + colIndex,
                    inputType: "textImage",
                    options: {
                        viewType: "icon",
                        imageSrc: "/SAMPLE/W5/project/dynamic/alz.jpg",
                        textAlign: "center"
                    }
                }
            } else {
                returnInfo = {
                    id: "dynamic_textImage_2_" + rowIndex + "_" + colIndex,
                    inputType: "textImage",
                    options: {
                        imageSrc: "/SAMPLE/W5/project/dynamic/alz.jpg",
                        textAlign: "center"
                    }
                }
            }
            break;
    }
    if (returnInfo) {
        console.log("[typeGetter] (" + rowIndex + ", " + colIndex + ") : " + returnInfo.inputType);
    }
    return returnInfo;
}
scwin.anchor1_onclick = function() {
    gridView3.advancedExcelDownload({
        type: 1,
        useFooter: true,
        useFooterData: true
    });
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.globalViewType = true;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
